styles.h1:
font-family: "SF Pro Display", "PingFang SC", "Helvetica Neue", sans-serif;
font-size: 24px;
position: relative;
color: #1e3a8a;
margin-bottom: 16px;
font-weight: 600;
text-align: left;
padding-bottom: 12px;
border-bottom: 1px solid #e5e7eb;

styles.h2:
font-size: 18px;
color: #1e3a8a;
margin-bottom: 16px;
font-weight: 500;
text-align: left;
position: relative;
padding: 8px 8px 8px 12px;
border-left: 3px solid #3b82f6;

styles.h3:
display: block;
color: #1e3a8a;
margin-bottom: 6px;
font-size: 16px;
font-weight: 600;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.a:
color: #2563eb;
text-decoration: none;
border-bottom: 1px solid rgba(37, 99, 235, 0.2);
transition: all 0.2s ease;

styles.li:
position: relative;


margin-bottom: 12px;
color: #334155;
line-height: 1.6;
font-size: 15px;

styles.blockquote:
background-color: #f8fafc;
border-left: 4px solid #3b82f6;
color: #475569;
padding: 12px 16px;
margin: 16px 0;
font-style: italic;

styles.pre:
border: 1px solid #e5e7eb;
background-color: #f8fafc;
border-radius: 4px;
padding: 12px;
overflow-x: auto;

styles.table:
border-collapse: collapse;
margin: 20px 0;
width: 100%;
border: 1px solid #e5e7eb;
box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);

styles.th:
background-color: #f8fafc;
color: #1e3a8a;
padding: 10px;
text-align: left;
border: 1px solid #e5e7eb;
font-weight: 600;

